export function applyGuideContentUpdates(pages) {
  return pages.map((page) => {
    const canonical = ['obx-homeowners-insurance', 'outer-banks-home-insurance'].includes(page.slug) ? H : page.slug;
    const update = updates[canonical];
    if (!update) return page;
    const { sourceKeys, nextStep, ...content } = update;
    return {
      ...page,
      ...content,
      localInsights: [],
      topicHelpText: nextStep,
      sources: sourceKeys.map((key) => sources[key]),
      lastReviewed: REVIEWED,
    };
  });
}

export const updatedGuideSlugs = Object.freeze(Object.keys(updates));
